// Same field-for-field result the file loader produces for the same values.
const Kernels& builtin_kernels() {
    static const Kernels kernels = [] {
        Kernels value;
        value.qmf_analysis.assign(qmf_analysis_coefficients,
                                  qmf_analysis_coefficients + kQmfAnalysisCount);
        value.hybrid_low.assign(hybrid_analysis_low_kernel,
                                hybrid_analysis_low_kernel + kHybridLowCount);
        value.hybrid_indices.assign(hybrid_synthesis_indices,
                                    hybrid_synthesis_indices + kHybridIndexCount);
        value.hybrid_values.assign(hybrid_synthesis_values,
                                   hybrid_synthesis_values + kHybridValueCount);
        value.qmf_basis.assign(qmf_synthesis_basis,
                               qmf_synthesis_basis + kQmfBasisCount);
        value.qmf_taps.assign(qmf_synthesis_taps,
                              qmf_synthesis_taps + kQmfTapsCount);
        value.hybrid_count = static_cast<std::uint32_t>(value.hybrid_values.size());
        return value;
    }();
    return kernels;
}

